    ('business_impact_nrx_biologic_include_synthetic', $kpi$SELECT base.*, (SELECT MAX(event_date) FROM treatment_events WHERE event_type::text = 'prescription')::date AS data_through FROM (SELECT COUNT(*) AS nrx FROM treatment_events WHERE event_type::text = 'prescription' AND sequence_number = 1 AND event_date >= (SELECT MAX(event_date) FROM treatment_events WHERE event_type::text = 'prescription') - INTERVAL '30 days' AND ($1::text IS NULL OR brand::text = $1) AND patient_id IN (SELECT patient_id FROM patient_journeys WHERE biologic_experienced IS NOT NULL AND CASE WHEN biologic_experienced = 1 THEN 'experienced' ELSE 'naive' END = $2)) base$kpi$, 2, $note$biologic-status-scoped NRx (includes synthetic)$note$),
